# Create custom dataset that handles corrupted images
from torchvision.datasets.folder import default_loader, IMG_EXTENSIONS

class RobustImageFolder(datasets.ImageFolder):
    def __init__(self, root, transform=None):
        super().__init__(root, transform=transform)

    def __getitem__(self, index):
        # Try to get the item, if it fails, skip to next valid image
        max_attempts = 10
        attempts = 0
        while attempts < max_attempts:
            try:
                path, target = self.samples[index]
                sample = self.loader(path)
                if self.transform is not None:
                    sample = self.transform(sample)
                if self.target_transform is not None:
                    target = self.target_transform(target)
                return sample, target
            except Exception:
                # If this image fails, try a different one
                index = (index + 1) % len(self.samples)
                attempts += 1
        # If all attempts fail, raise the original error
        raise RuntimeError(f"Could not load a valid image after {max_attempts} attempts")

